const CACHE='warm-circle-v6';const CORE=['./','./index.html','./style.css','./app.js','./manifest.webmanifest','./icon.svg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(CORE)));self.skipWaiting()});
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;const pathname=new URL(event.request.url).pathname;const shell=CORE.some(path=>pathname.endsWith(path.replace('./','')))||pathname.endsWith('/');if(!shell)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok)caches.open(CACHE).then(cache=>cache.put(event.request,response.clone()));return response}).catch(()=>caches.match(event.request).then(cached=>cached||caches.match('./index.html'))))});
self.addEventListener('push',event=>{let data={title:'Новое сообщение',body:'Кто-то из семьи написал вам',url:''};try{data={...data,...event.data?.json()}}catch{}const appRoot=new URL('./',self.registration.scope).href;const target=new URL(String(data.url||'').replace(/^\/+/,''),appRoot).href;const icon=new URL('icon.svg',appRoot).href;event.waitUntil(self.registration.showNotification(data.title,{body:data.body,icon,badge:icon,tag:'family-message',data:{url:target},renotify:true}))});
self.addEventListener('notificationclick',event=>{event.notification.close();const appRoot=new URL('./',self.registration.scope).href;const target=new URL(String(event.notification.data?.url||'').replace(/^\/+/,''),appRoot).href;event.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(windows=>{const existing=windows.find(client=>new URL(client.url).origin===self.location.origin);if(existing){existing.navigate(target);return existing.focus()}return self.clients.openWindow(target)}))});
